import{_ as a,o as r,c as s,a2 as t}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"教程","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/index.md","filePath":"zh/guides/index.md","lastUpdated":1788855895000}'),o={name:"zh/guides/index.md"};function i(h,e,l,n,g,d){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="教程" tabindex="-1">教程 <a class="header-anchor" href="#教程" aria-label="Permalink to &quot;教程&quot;">​</a></h1><p>这些教程从产品使用流程出发，默认你已经能访问 Memoh，需要创建机器人、管理会话、连接工具，并使用日常功能。</p><h2 id="开始使用-memoh" tabindex="-1">开始使用 Memoh <a class="header-anchor" href="#开始使用-memoh" aria-label="Permalink to &quot;开始使用 Memoh&quot;">​</a></h2><ul><li><strong><a href="/zh/guides/quick-start.html">快速开始</a></strong>：部署服务端、添加模型、创建第一个机器人并接入渠道。</li><li><strong><a href="/zh/guides/preferences.html">用户偏好</a></strong>：配置界面语言、主题、字体、图表和快捷键。</li><li><strong><a href="/zh/guides/bot.html">机器人</a></strong>：创建机器人并配置核心标签页。</li><li><strong><a href="/zh/guides/sessions.html">会话</a></strong>：理解 chat、discuss、路由和状态区。</li><li><strong><a href="/zh/guides/files.html">文件</a></strong>：浏览和编辑机器人 workspace 文件。</li><li><strong><a href="/zh/guides/memory.html">长期记忆</a></strong>：在配置好记忆提供方后管理长期记忆条目。</li></ul><h2 id="扩展机器人能力" tabindex="-1">扩展机器人能力 <a class="header-anchor" href="#扩展机器人能力" aria-label="Permalink to &quot;扩展机器人能力&quot;">​</a></h2><ul><li><strong><a href="/zh/guides/skills.html">技能</a></strong> 和 <strong><a href="/zh/guides/supermarket.html">应用市场</a></strong>：添加可复用提示模块和模板。</li><li><strong><a href="/zh/guides/hooks.html">Hooks</a></strong> 和 <strong><a href="/zh/guides/mcp.html">MCP</a></strong>：连接工具、自动化规则和外部数据源。</li><li><strong><a href="/zh/guides/browser-computer-use.html">Browser / Computer Use</a></strong>：使用有头浏览器和可见桌面会话。</li><li><strong><a href="/zh/guides/slash-commands.html">斜杠命令</a></strong>：用命令快捷完成日常控制。</li></ul><h2 id="权限与运行" tabindex="-1">权限与运行 <a class="header-anchor" href="#权限与运行" aria-label="Permalink to &quot;权限与运行&quot;">​</a></h2><ul><li><strong><a href="/zh/guides/access.html">访问控制</a></strong>：配置 ACL 预设、规则顺序和来源限定。</li><li><strong><a href="/zh/guides/container.html">Workspace</a></strong>：从产品界面理解 workspace 行为。</li><li><strong><a href="/zh/guides/compaction.html">上下文压缩</a></strong>：缩小当前会话上下文占用。</li><li><strong><a href="/zh/guides/schedule.html">计划任务</a></strong>：按 cron 计划运行周期性工作，无需活跃聊天。</li><li><strong><a href="/zh/guides/email.html">邮件</a></strong>：配置邮件相关工作流。</li></ul><h2 id="其他文档区域" tabindex="-1">其他文档区域 <a class="header-anchor" href="#其他文档区域" aria-label="Permalink to &quot;其他文档区域&quot;">​</a></h2><ul><li><strong><a href="/zh/integrations/">集成</a></strong>：连接渠道和提供方。</li><li><strong><a href="/zh/self-hosted/">自托管</a></strong>：部署和运维自己的 Memoh 实例。</li></ul>',10)])])}const c=a(o,[["render",i]]);export{m as __pageData,c as default};
